class Solution { public:
 int minSizeSubarray(vector<int>& nums,int target){
  long long total=accumulate(nums.begin(),nums.end(),0LL),cycles=target/total,rem=target%total;
  if(rem==0)return (int)(cycles*nums.size());
  int n=nums.size(),l=0,best=INT_MAX;long long sum=0;
  for(int r=0;r<2*n;++r){sum+=nums[r%n];while(sum>rem){sum-=nums[l%n];++l;}
   if(sum==rem)best=min(best,r-l+1);
  }
  return best==INT_MAX?-1:(int)(cycles*n+best);
 }
};
